mapper.select:
SELECT id, tenant_id, user_id, selected_model_id, preference_json, revision, created_at, updated_at
FROM ds_user_model_preference
WHERE tenant_id = #{tenantId} AND user_id = #{userId}

mapper.update:
UPDATE ds_user_model_preference
SET selected_model_id = #{entity.selectedModelId}, preference_json = #{entity.preferenceJson},
    revision = revision + 1, updated_at = #{now}
WHERE tenant_id = #{entity.tenantId} AND user_id = #{entity.userId}
  AND revision = #{expectedRevision}
